    } else {
      state = this.tracker.create({
        runId: params.runIdFactory(),
        repoCwd: params.repoCwd,
        startCommit: params.startCommit,
        scheduler: params.scheduler,
        rollbackSnapshotId: snapshot.snapshotDirectory,
        capturePromptTranscripts: this.capturePromptTranscripts,
