export function applyLoopRunEventToInkState(
  state: InkRunViewState,
  event: LoopRunEvent,
  at: string,
): InkRunViewState {
  switch (event.kind) {
    case "taskPhaseChanged": {
      const workerProjection = applyTaskPhaseToWorkerProjection(state, event, at);
      let updatedState: InkRunViewState = { ...state, ...workerProjection };
      if (event.from !== null) {
        const separator = `── ${String(event.from)} → ${String(event.to)} ──`;
        const sourceKey = `issue:${workerKey(event.issueId)}`;
        const partial = appendLogFragment(updatedState, sourceKey, event.issueId, event.to, separator, true, at);
        updatedState = { ...updatedState, ...partial };
      }
      return updatedState;
    }

    case "taskMetaChanged": {
      const workerProjection = applyTaskMetaToWorkerProjection(state, event.issueId, event.meta);
      return workerProjection === null ? state : { ...state, ...workerProjection };
    }

    case "usageRecorded": {
      const workerProjection = applyUsageRecordedToWorkerProjection(state, event.entry, at);
      return { ...state, ...workerProjection };
    }

    case "streamingUsage": {
      const workerProjection = applyStreamingUsageToWorkerProjection(state, event.issueId, event.usage);
      return workerProjection === null ? state : { ...state, ...workerProjection };
    }

    case "runFinished":
      return { ...state, overlay: { kind: "run-finished", outcome: event.outcome } };

    default:
      return state;
  }
}

export function appendRunLogEntryToInkState(
  state: InkRunViewState,
  entry: RunLogEntry,
  at: string,
): InkRunViewState {
  const sourceKey = entry.kind === "issue-text" ? `issue:${String(entry.issueId)}` : "run";
  const issueId = entry.kind === "issue-text" ? entry.issueId : undefined;
  let nextState = state;
  let remaining = entry.text;

  while (remaining.length > 0) {
    const newlineIndex = remaining.indexOf("\n");
    if (newlineIndex === -1) {
      const phase = getWorkerPhase(nextState, issueId);
      const partial = appendLogFragment(nextState, sourceKey, issueId, phase, remaining, false, at);
      const touched = touchWorkerLatestAt(nextState, issueId, at);
      nextState = { ...nextState, ...partial, ...(touched ?? {}) };
      break;
    }

    const line = remaining.slice(0, newlineIndex);
    const phase = getWorkerPhase(nextState, issueId);
    const closed = appendLogFragment(nextState, sourceKey, issueId, phase, line, true, at);
    const touched = touchWorkerLatestAt(nextState, issueId, at);
    nextState = { ...nextState, ...closed, ...(touched ?? {}) };
    remaining = remaining.slice(newlineIndex + 1);

    if (remaining.length === 0 && entry.text.endsWith("\n")) {
      break;
    }
  }

  return nextState;
}

