  private pruneArchive(): void {
    if (!existsSync(this.archiveDir)) return;

    const files = readdirSync(this.archiveDir, { withFileTypes: true })
      .filter((f) => f.isFile() && f.name.endsWith(".json"))
      .map((f) => ({
        name: f.name,
        mtime: statSync(join(this.archiveDir, f.name)).mtimeMs,
      }))
      .sort((a, b) => b.mtime - a.mtime);

    const toRemove = files.slice(10);
    const promptsDir = join(this.cwd, PROMPTS_DIR);
    const criterionEvidenceDir = join(this.cwd, CRITERION_EVIDENCE_DIR);

    for (const file of toRemove) {
      // Read the archived file to extract runId before deleting
      try {
        const raw = readFileSync(join(this.archiveDir, file.name), "utf8");
        const state = JSON.parse(raw) as RunSnapshot;
        const runPromptsDir = join(promptsDir, state.runId);
        if (existsSync(runPromptsDir)) {
          rmSync(runPromptsDir, { recursive: true, force: true });
        }
        const runCriterionEvidenceDir = join(criterionEvidenceDir, state.runId);
        if (existsSync(runCriterionEvidenceDir)) {
          rmSync(runCriterionEvidenceDir, { recursive: true, force: true });
        }
        const handoffDir = join(this.cwd, HANDOFF_DIR);
        const runHandoffDir = join(handoffDir, state.runId);
        if (existsSync(runHandoffDir)) {
          rmSync(runHandoffDir, { recursive: true, force: true });
        }
      } catch {
        // File may be malformed; skip artifact cleanup for this entry
      }

      rmSync(join(this.archiveDir, file.name), { force: true });
    }
  }

  private ensureDirs(): void {
    if (!existsSync(this.runsDir)) {
      mkdirSync(this.runsDir, { recursive: true });
    }
  }

  recordPhase(issueId: IssueId, phase: TaskPhase): void {
    this.update((s) => {
      const key = String(issueId);
      const existing = s.tasks[key];
      if (!existing) {
        return {
          ...s,
          tasks: {
            ...s.tasks,
            [key]: {
              issueId,
              title: "",
              body: "",
              phase,
              attempt: 0,
            },
          },
        };
      }
      return {
        ...s,
        tasks: {
          ...s.tasks,
          [key]: { ...existing, phase },
        },
      };
    });
  }

  recordMeta(issueId: IssueId, meta: TaskMeta): void {
    this.update((s) => {
      const key = String(issueId);
      const existing = s.tasks[key];
      if (!existing) return s;
      return {
        ...s,
        tasks: {
          ...s.tasks,
          [key]: { ...existing, ...meta },
        },
      };
    });
  }

  recordSchedulerProgress(progress: SchedulerProgress): void {
    this.update((s) => ({
      ...s,
      scheduler: {
        ...s.scheduler,
        ...(progress.iterationsStarted !== undefined ? { iterationsStarted: progress.iterationsStarted } : {}),
        ...(progress.skippedIds !== undefined ? { skippedIds: progress.skippedIds } : {}),
      },
    }));
  }

  restartTask(issueId: IssueId): void {
    this.update((state) => {
      const key = String(issueId);
      const existing = state.tasks[key];
      if (!existing) return state;
      return {
        ...state,
        tasks: {
          ...state.tasks,
          [key]: {
            ...existing,
            phase: "scheduled",
            integratedHead: undefined,
            preMergeHead: undefined,
            lastError: undefined,
          },
        },
      };
    });
  }

  normalizeLiveSteeringPostCrash(): void {
    this.update((state) => ({
      ...state,
      tasks: Object.fromEntries(
        Object.entries(state.tasks).map(([id, task]) => [
          id,
          {
            ...task,
            liveSteering: normalizeSteeringPostCrash(task.liveSteering ?? []),
          },
        ]),
      ),
    }));
  }

  private atomicWrite(state: RunSnapshot): void {
    this.ensureDirs();
    const tmpPath = this.activeFilePath + ".tmp";
    writeFileSync(tmpPath, JSON.stringify(state, null, 2), "utf8");

    try {
      renameSync(tmpPath, this.activeFilePath);
    } catch (error) {
      if (!isWindowsRenameCollision(error)) {
        throw error;
      }
      rmSync(this.activeFilePath, { force: true });
      renameSync(tmpPath, this.activeFilePath);
    }
  }
}

function isWindowsRenameCollision(error: unknown): boolean {
  const code = (error as NodeJS.ErrnoException | undefined)?.code;
  return code === "EPERM" || code === "EEXIST" || code === "EBUSY";
}

