export interface PromptTranscriptManifestRef {
  path: string;
  sha256: string;
}

export type PromptTranscriptsState =
  | { enabled: false }
  | { enabled: true; manifest?: PromptTranscriptManifestRef };

export type PromptPhase = "implement" | "verify" | "merger" | "review" | "live-steering";

export type PromptClientKind = "claude" | "opencode" | "pi" | "custom";

export type CriterionStatus = "met" | "unmet" | "regressed";

export interface CriterionVerdict {
  id: string;
  status: CriterionStatus;
  evidenceProse: string;
  evidenceRef: string | null;
}

export interface PerModelUsage {
  model: string;
  inputTokens: number | null;
  outputTokens: number | null;
  cacheReadTokens: number | null;
  cacheWriteTokens: number | null;
  reasoningTokens: number | null;
  costUsd: number | null;
}

export interface AgentExecutionUsage {
  inputTokens: number | null;
  outputTokens: number | null;
  cacheReadTokens: number | null;
  cacheWriteTokens: number | null;
  reasoningTokens: number | null;
  totalTokens: number | null;
  /**
   * Latest context-window snapshot for the currently running parent agent.
   * Unlike `totalTokens`, this is not cumulative across multiple assistant
   * turns in one execution.
   */
  contextTokens?: number | null;
  /** Context window size for the model running this phase. */
  maxContext?: number | null;
  costUsd: number | null;
  perModelUsage?: PerModelUsage[];
}

export interface UsageLedgerEntry extends AgentExecutionUsage {
  executionId: number;
  phase: PromptPhase;
  issueId?: IssueId;
  attempt?: number;
  client: PromptClientKind;
  model?: string;
  outcome: "succeeded" | "failed";
  error?: string;
}

export interface UsageTotals {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheWriteTokens: number;
  reasoningTokens: number;
  totalTokens: number;
  costUsd: number;
  hasUnknownTokens: boolean;
  hasUnknownCost: boolean;
