/**
 * Adapter that bridges the legacy caller-supplied `TaskPhaseTracker`
 * contract to Loop Run fact events.
 *
 * Replaces `combineTrackers` in `ralph-loop.ts`. The Loop Run is the sole
 * writer of the internal Durable Loop Run Tracker; an external
 * `TaskPhaseTracker` provided by a caller is now a read-only observer
 * driven from fact events instead of a parallel co-writer.
 *
 * See ADR-0007.
 */

import type { TaskPhaseTracker } from "./external-tracker.js";
import type { LoopRunSubscriber } from "./events.js";

export function externalPhaseObserver(external: TaskPhaseTracker): LoopRunSubscriber {
  return (event) => {
    switch (event.kind) {
      case "taskPhaseChanged":
        if (event.meta) external.recordMeta(event.issueId, event.meta);
        external.recordPhase(event.issueId, event.to);
        return;
      case "taskMetaChanged":
        external.recordMeta(event.issueId, event.meta);
        return;
      case "schedulerProgressed":
        external.recordSchedulerProgress({
          iterationsStarted: event.iterationsStarted,
          skippedIds: event.skippedIds,
        });
        return;
      default:
        // External TaskPhaseTracker has no contract for review phase,
        // snapshot lifecycle, panic-undo, or run completion. Other
        // subscribers handle those joints.
        return;
    }
  };
}

